-- Output perawatan = Ha dikerjakan / HK bekerja. Sumber INT_RAWAT_HARIAN (UOM=HA; HK = jumlah NIK-hari berbeda) dan INT_RAWAT_TARGET (QTY_TARGET, hanya kode aktivitas ber-UOM HA).
-- Pemetaan aktivitas -> Cost Level 1: nama aktivitas dinormalkan (buang awalan TM/TBM/MN/PN/RA/GC dan akhiran LABOR/PIECE RATED) lalu dicocokkan dengan LEVEL_2 ESTATE_COST; yang tidak cocok dipetakan manual (tabel mp). Pupuk, GC, MN, PN, RA dan SANITATION tidak dimasukkan.
-- Hasil: kolom j (JSON per afd) -> rawat_load.py (r_rawout.json). Ganti '2026-09-01' dan batas tanggal sesuai bulan laporan.
WITH lv AS (SELECT column1 l1, column2 i FROM VALUES ('HPT',0),('PEMBERANTASAN LALANG',1),('PENJARANGAN',2),('PERALATAN KERJA RAWAT',3),('PERAWATAN GAWANGAN',4),('PIRINGAN, PASAR PIKUL, TPH',5),('SENSUS TANAMAN',6),('SISIP TANAMAN',7),('SUPERVISI PEMELIHARAAN',8),('TRANSPORT RAWAT',9),('TUNASAN / PRUNING / SLASHING',10),('MANAGEMENT MILL',11),('PEMELIHARAAN INFRASTRUKTUR LAINNYA',12),('PEMELIHARAAN JALAN',13),('PEMELIHARAAN JEMBATAN',14),('PEMELIHARAAN KONSERVASI TANAH',15),('PEMELIHARAAN PARIT',16),('PEMELIHARAAN TAPAK KUDA',17),('PRUNING PINGGIR JALAN',18),('SISIP JALAN',19)),
mp AS (SELECT column1 k, column2 l1 FROM VALUES ('CIRCLE WEEDING','PIRINGAN, PASAR PIKUL, TPH'),('CATERPILLAR/WORM BAG/TERMITES CONTROL','HPT'),('DONGKEL ANAK KAYU','PERAWATAN GAWANGAN'),('DONGKEL ANAK KAYU - ELIMINASI','PERAWATAN GAWANGAN'),('OLES ANAK KAYU','PERAWATAN GAWANGAN'),('CPT SPRAYING KNAPSACK','PIRINGAN, PASAR PIKUL, TPH'),('CPT SPRAYING MHS','PIRINGAN, PASAR PIKUL, TPH'),('OTHER PESTS CONTROL','HPT'),('PEST DETECTION','HPT'),('BENEFICIAL WEEDS PLANT AND UPKEEP','HPT'),('RODENT PESTS CONTROL','HPT'),('SPOT LALANG','PEMBERANTASAN LALANG'),('SPOT SPRAYING - ELIMINASI','PERAWATAN GAWANGAN'),('SLASHING GULMA - MEKANIS','PERAWATAN GAWANGAN'),('SEMPROT KENTOSAN','PERAWATAN GAWANGAN'),('PRUNNING PROGRESS','TUNASAN / PRUNING / SLASHING'),('PRUNING PROGRESSIVE (DODOS)','TUNASAN / PRUNING / SLASHING'),('CENSUS','SENSUS TANAMAN'),('VEGETATIVE CENSUS','SENSUS TANAMAN')),
l2 AS (SELECT UPPER(REPLACE(LEVEL_2,'/ ','/')) k, MIN(LEVEL_1) l1 FROM PRD_DB_PRESENTATION.PRS_COST.ESTATE_COST WHERE GROUP_LEVEL IN ('BIAYA PERAWATAN','BIAYA INFRA') GROUP BY 1),
h AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, KODE_AKTIFITAS code, TANGGAL_RAWAT d, NIK_KARYAWAN nik, HASIL_AKTIFITAS ha, REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(UPPER(NAMA_AKTIFITAS),'^(TM|TBM|MN|PN|RA|GC|TC) - ',''),' *- *(LABORS?|PIECE RATED|CONTRACTS?)$',''),'/ ','/') k
 FROM PRD_DB_INTEGRATION.INT_RAWAT.INT_RAWAT_HARIAN WHERE KODE_BA IN ('2121','2124','2131','2122') AND NOT (DECODE(KODE_BA,'2122','2131',KODE_BA)='2131' AND KODE_AFD='B') AND TANGGAL_RAWAT>='2026-01-01' AND TANGGAL_RAWAT<'2026-10-01' AND UOM_AKTIFITAS='HA' AND UPPER(NAMA_AKTIFITAS) NOT LIKE '%FERTILIZER%' AND UPPER(NAMA_AKTIFITAS) NOT LIKE '%MANURING%' AND UPPER(NAMA_AKTIFITAS) NOT LIKE '%ABU BOILER%' AND REGEXP_LIKE(UPPER(NAMA_AKTIFITAS),'^(TM|TBM) - .*')),
hm AS (SELECT h.*, lv.i FROM h JOIN (SELECT k, l1 FROM mp UNION ALL SELECT k, l1 FROM l2 WHERE k NOT IN (SELECT k FROM mp)) m ON h.k=m.k JOIN lv ON lv.l1=m.l1),
a AS (SELECT ba, afd, i, ROUND(SUM(ha),1) hay, COUNT(DISTINCT nik||d) hky, ROUND(SUM(IFF(d>='2026-09-01',ha,0)),1) ham, COUNT(DISTINCT IFF(d>='2026-09-01',nik||d,NULL)) hkm FROM hm GROUP BY 1,2,3),
tg AS (SELECT DECODE(t.KODE_BA,'2122','2131',t.KODE_BA) ba, t.KODE_AFD afd, lv.i, ROUND(SUM(t.QTY_TARGET),1) tgy, ROUND(SUM(IFF(t.BULAN='2026-09-01',t.QTY_TARGET,0)),1) tgm
 FROM PRD_DB_INTEGRATION.INT_RAWAT.INT_RAWAT_TARGET t JOIN (SELECT DISTINCT code FROM h) c ON t.KODE_AKTIVITAS_SAP=c.code
 JOIN (SELECT DISTINCT code, k FROM h) hk ON hk.code=c.code JOIN (SELECT k, l1 FROM mp UNION ALL SELECT k, l1 FROM l2 WHERE k NOT IN (SELECT k FROM mp)) m ON hk.k=m.k JOIN lv ON lv.l1=m.l1
 WHERE t.KODE_BA IN ('2121','2124','2131','2122') AND NOT (DECODE(t.KODE_BA,'2122','2131',t.KODE_BA)='2131' AND t.KODE_AFD='B') AND t.BULAN>='2026-01-01' AND t.BULAN<'2026-10-01' GROUP BY 1,2,3),
u AS (SELECT ba, afd, i FROM a UNION SELECT ba, afd, i FROM tg)
SELECT u.ba, u.afd, OBJECT_AGG(u.i::STRING, ARRAY_CONSTRUCT(COALESCE(a.hay,0),COALESCE(a.hky,0),COALESCE(tg.tgy,0),COALESCE(a.ham,0),COALESCE(a.hkm,0),COALESCE(tg.tgm,0)))::STRING j
FROM u LEFT JOIN a ON a.ba=u.ba AND a.afd=u.afd AND a.i=u.i LEFT JOIN tg ON tg.ba=u.ba AND tg.afd=u.afd AND tg.i=u.i GROUP BY 1,2 ORDER BY 1,2;
